public static int calculateTimeNeeded(int N) {
    // If there are three or fewer people, no time is needed to reverse the seating order.
    if (N <= 3) {
        return 0;
    }
    // For more than three people, the time needed grows linearly: 2 minutes for each
    // person beyond the third.
    return 2 * (N - 3);
}

public static int calculateTimeNeeded(int N) {
    // The time needed to reverse the seating order follows the pattern:
    // time = 2 * (N - 3) for N >= 3.
    // For N less than 3, zero time is required (no meaningful reversal).
    if (N < 3) {
        return 0;
    }
    return 2 * (N - 3);
}

