    // The time needed increases by 2 minutes for each person above 3.
    // For N <= 3 the reverse order is trivial, requiring no time.
    return Math.max(0, 2 * (N - 3));
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, 0, res);
    return res;
}

private void backtrack(int[] nums, int start, List<List<Integer>> res) {
    if (start == nums.length) {
        List<Integer> cur = new ArrayList<>();
        for (int num : nums) {
            cur.add(num);
        }
        res.add(cur);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        backtrack(nums, start + 1, res);
        swap(nums, start, i);
    }
}

private void swap(int[] a, int i, int j) {
    int temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    res.add(new java.util.ArrayList<Integer>());
    for (int num : nums) {
        java.util.List<java.util.List<Integer>> newRes = new java.util.ArrayList<>();
        for (java.util.List<Integer> perm : res) {
            for (int pos = 0; pos <= perm.size(); pos++) {
                java.util.List<Integer> newPerm = new java.util.ArrayList<>(perm);
                newPerm.add(pos, num);
                newRes.add(newPerm);
            }
        }
        res = newRes;
    }
    return res;
}

public List<List<Integer>> permute(int[] nums) {
