public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = 0;
    int n = strings.size();
    int firstLen = first.length();
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            String sub = first.substring(i, j);
            int len = sub.length();
            if (len <= maxLen) {
                continue;
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < n; k++) {
                String s = strings.get(k);
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = len;
            }
        }
    }
    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to reduce candidates
    int minIdx = 0;
    for (int i = 1; i < strings.size(); ++i) {
        if (strings.get(i).length() < strings.get(minIdx).length()) {
            minIdx = i;
        }
    }
    String base = strings.get(minIdx);
    int baseLen = base.length();
    // Iterate lengths from longest to shortest
    for (int len = baseLen; len >= 1; --len) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= baseLen - len; ++i) {
            String sub = base.substring(i, i + len);
            candidates.add(sub);
            String rev = new StringBuilder(sub).reverse().toString();
            candidates.add(rev);
        }
        for (String candidate : candidates) {
            String revCand = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!s.contains(candidate) && !s.contains(revCand)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to reduce the search space
    int minLen = Integer.MAX_VALUE;
    int minIdx = 0;
    for (int i = 0; i < strings.size(); i++) {
        String s = strings.get(i);
        if (s.length() < minLen) {
            minLen = s.length();
            minIdx = i;
        }
    }
    String base = strings.get(minIdx);
    if (minLen == 0) {
        return 0;
    }

    // Try lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Use a set to avoid duplicate substrings of the same length
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (int i = 0; i <= base.length() - len; i++) {
            String sub = base.substring(i, i + len);
            if (seen.contains(sub)) {
                continue;
            }
            seen.add(sub);
            String rev = new StringBuilder(sub).reverse().toString();

            boolean ok = true;
            for (int j = 0; j < strings.size(); j++) {
                if (j == minIdx) {
                    continue; // base string already contains sub
                }
                String s = strings.get(j);
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Compute the minimum string length to set the upper bound
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }

    String first = strings.get(0);
    // Iterate from the largest possible length down to 1
    for (int L = minLen; L >= 1; L--) {
        // Generate all candidate substrings of length L from the first string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + L <= first.length(); i++) {
            candidates.add(first.substring(i, i + L));
        }

        // For each candidate, check against all strings
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return L;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    int n = grid.length;
    if (n == 0) return 0;
    int m = grid[0].length;
    if (m == 0) return 0;
    boolean[][] visited = new boolean[n][m];
    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    int maxSize = n * m;
    int[] stackR = new int[maxSize];
    int[] stackC = new int[maxSize];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                deposits++;
                int top = 0;
                visited[i][j] = true;
                stackR[top] = i;
                stackC[top] = j;
                top++;
                while (top > 0) {
                    top--;
                    int r = stackR[top];
                    int c = stackC[top];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stackR[top] = nr;
                                stackC[top] = nc;
                                top++;
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

