public static int countDoubles(int[] numbers) {
    // Frequency map of each number
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 != 0) {
            continue; // only even numbers can be double of some integer
        }
        int target = n / 2;
        Integer targetCount = freq.get(target);
        if (targetCount == null) {
            continue;
        }
        // Ensure we are not counting the same element as itself unless there is another occurrence
        if (target != n || targetCount >= 2) {
            count++;
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    // Store all numbers in a set for O(1) lookups
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int n : numbers) {
        set.add(n);
    }

    int count = 0;
    for (int n : numbers) {
        // If n is not even, it cannot be twice another integer
        if ((n & 1) == 0) { // faster modulo check for evenness
            int half = n / 2;
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

