    for (int num : numbers) {
        if ((num & 1) == 0) { // check even
            if (set.contains(num / 2)) {
                count++;
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    java.util.Set<String> nodes = new java.util.HashSet<>();
    java.util.function.Function<int[], String> toKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = toKey.apply(start);
    String endKey = toKey.apply(end);
    nodes.add(startKey);
    nodes.add(endKey);
    for (int[] path : paths) {
        if (path.length != 2 * n) continue;
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = toKey.apply(a);
        String bKey = toKey.apply(b);
        nodes.add(aKey);
        nodes.add(bKey);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }
    if (startKey.equals(endKey)) return "can be travelled";
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String curr = queue.poll();
        java.util.List<String> neighbors = adj.get(curr);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (visited.contains(nb)) continue;
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input sizes
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (n <= 0) {
        return "cannot be travelled";
    }
    // Check that coordinates are within bounds
    if (!inBounds(start[0], start[1], n) || !inBounds(end[0], end[1], n)) {
        return "cannot be travelled";
    }
    // If start and end are the same point
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    int totalNodes = n * n;
    java.util.List<int[]>[] adjacency = new java.util.ArrayList[totalNodes];
    for (int i = 0; i < totalNodes; i++) {
        adjacency[i] = new java.util.ArrayList<>();
    }

    for (int[] path : paths) {
        if (path == null || path.length != 4) {
            continue; // skip invalid path definitions
        }
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        if (!inBounds(x1, y1, n) || !inBounds(x2, y2, n)) {
            continue; // ignore out-of-bounds
        }
        int id1 = x1 * n + y1;
        int id2 = x2 * n + y2;
        adjacency[id1].add(new int[]{x2, y2});
        adjacency[id2].add(new int[]{x1, y1});
    }

    // BFS from start to find end
    java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
    boolean[] visited = new boolean[totalNodes];
    int startId = start[0] * n + start[1];
    queue.add(start);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        int curId = cur[0] * n + cur[1];
        for (int[] neighbor : adjacency[curId]) {
            int nx = neighbor[0], ny = neighbor[1];
            int nid = nx * n + ny;
            if (!visited[nid]) {
                if (nx == end[0] && ny == end[1]) {
                    return "can be travelled";
                }
                visited[nid] = true;
                queue.add(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

private static boolean inBounds(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
