    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    int dim = start.length;
    // Populate graph from paths
    for (int i = 0; i < paths.length; i++) {
        int[] row = paths[i];
        if (row.length != 2 * dim) {
            // Unsupported format
            continue;
        }
        int[] a = new int[dim];
        int[] b = new int[dim];
        System.arraycopy(row, 0, a, 0, dim);
        System.arraycopy(row, dim, b, 0, dim);
        String keyA = coordToKey.apply(a);
        String keyB = coordToKey.apply(b);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) continue;
        for (String nbr : neighbors) {
            if (nbr.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(nbr)) {
                queue.add(nbr);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // If start and end are the same coordinates, travel is trivially possible
    if (start.length >= 2 && end.length >= 2 &&
        start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency map where each node is represented by "x#y"
    java.util.HashMap<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] path : paths) {
        // Expect each path to contain four integers: x1, y1, x2, y2
        if (path.length < 4) {
            continue; // skip invalid path entries
        }
        String a = path[0] + "#" + path[1];
        String b = path[2] + "#" + path[3];

        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    // Prepare BFS
    String startKey = start[0] + "#" + start[1];
    String endKey = end[0] + "#" + end[1];

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        if (curr.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.getOrDefault(curr, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (visited.add(nb)) {
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate to string key
    java.util.function.Function<int[], String> toKey = (coord) -> coord[0] + "," + coord[1];
    java.util.HashMap<String, java.util.List<String>> adj = new java.util.HashMap<>();
    // Build adjacency list from paths
    for (int[] p : paths) {
        if (p.length < 4) continue; // invalid path entry
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        String key1 = x1 + "," + y1;
        String key2 = x2 + "," + y2;
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }
    String startKey = toKey.apply(start);
    String endKey = toKey.apply(end);
    if (startKey.equals(endKey)) return "can be travelled";
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
    visited.add(startKey);
    queue.add(startKey);
    while (!queue.isEmpty()) {
