            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    java.util.Calendar cal = new java.util.GregorianCalendar(year, month - 1, day);
    int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK);

    String[] monthNames = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};
    String[] weekNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    String monthName = monthNames[month - 1];
    String weekName = weekNames[dayOfWeek - 1];

    return monthName + " " + day + ", " + year + " is a " + weekName;
}

