public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    double sum = 0.0;
    int remaining = n - 2 * k;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    return sum / remaining;
}

