public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[Math.max(k, 1)];
    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        freq[mod]++;
    }
    if (freq[0] % 2 != 0) return false;
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[k - r]) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false;
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int r = entry.getKey();
        int cnt = entry.getValue();
        if (r == 0) {
            if (cnt % 2 != 0) return false;
        } else if (k % 2 == 0 && r == k / 2) {
            if (cnt % 2 != 0) return false;
        } else {
            int complement = k - r;
            int compCnt = freq.getOrDefault(complement, 0);
            if (cnt != compCnt) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if ((arr.length & 1) == 1) { // n must be even
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        count[rem]++;
    }
    // Remainder 0 must have even count
    if ((count[0] & 1) == 1) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // this only happens when k is even and r == k/2
            if ((count[r] & 1) == 1) {
                return false;
            }
        } else {
            if (count[r] != count[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) return false;

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;   // handle negative numbers
        freq[r]++;
    }

    // Elements with remainder 0 must pair among themselves
    if (freq[0] % 2 != 0) return false;

    // If k is even, elements with remainder k/2 must also pair among themselves
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // For all other remainders r, freq[r] must equal freq[k - r]
    for (int r = 1; r <= k / 2; r++) {
        // Skip the special case when r == k - r (only possible when k is even and r == k/2)
        if (r == k - r) continue;
        if (freq[r] != freq[k - r]) return false;
    }

    return true;
}

