    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }

    if (freq[0] % 2 != 0) return false; // pairs of 0 remainder need even count

    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // when k is even and i == k/2
            if (freq[i] % 2 != 0) return false;
        } else {
            if (freq[i] != freq[k - i]) return false;
        }
    }

    return true;
}

