public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<Integer>();
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    parent[0] = -1;
    int[] order = new int[n];
    int idx = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<Integer>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int child : graph[node]) {
            if (child != parent[node]) {
                parent[child] = node;
                stack.push(child);
            }
        }
    }
    int res = 0;
    boolean[] need = new boolean[n];
    System.arraycopy(hasApple, 0, need, 0, n);
    for (int i = idx - 1; i > 0; i--) { // skip root at index 0
        int node = order[i];
        if (need[node]) {
            res += 2;
            need[parent[node]] = true;
        }
    }
    return res;
}

