public String sortString(String s) {
    int[] freq = new int[256];
    for (char ch : s.toCharArray()) {
        freq[ch]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int processed = 0;
    int total = s.length();
    while (processed < total) {
        // Ascending pass: from smallest to largest
        for (int i = 0; i < 256; i++) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                processed++;
            }
        }
        // Descending pass: from largest to smallest
        for (int i = 255; i >= 0; i--) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                processed++;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    StringBuilder res = new StringBuilder();
    int total = s.length();

    while (res.length() < total) {
        // Pick the smallest character
        Map.Entry<Character, Integer> smallest = freq.firstEntry();
        char last = smallest.getKey();
        res.append(last);
        int cnt = smallest.getValue() - 1;
        if (cnt == 0) freq.remove(last);
        else freq.put(last, cnt);

        // Continue picking smallest characters greater than the last appended
        while (true) {
            Map.Entry<Character, Integer> higher = freq.higherEntry(last);
            if (higher == null) break;
            last = higher.getKey();
            res.append(last);
            int c = higher.getValue() - 1;
            if (c == 0) freq.remove(last);
            else freq.put(last, c);
        }

        if (res.length() >= total) break;

        // Pick the largest character
        Map.Entry<Character, Integer> largest = freq.lastEntry();
        char lastLarge = largest.getKey();
        res.append(lastLarge);
        int cntLarge = largest.getValue() - 1;
        if (cntLarge == 0) freq.remove(lastLarge);
        else freq.put(lastLarge, cntLarge);

        // Continue picking largest characters smaller than the last appended
        while (true) {
            Map.Entry<Character, Integer> lower = freq.lowerEntry(lastLarge);
            if (lower == null) break;
            lastLarge = lower.getKey();
            res.append(lastLarge);
            int c = lower.getValue() - 1;
            if (c == 0) freq.remove(lastLarge);
            else freq.put(lastLarge, c);
        }
    }
    return res.toString();
}

public String sortString(String s) {
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        map.put(ch, map.getOrDefault(ch, 0) + 1);
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (!map.isEmpty()) {
        // Step 1: pick smallest character
        char c = map.firstKey();
        sb.append(c);
        if (map.get(c) == 1) map.remove(c);
        else map.put(c, map.get(c) - 1);

        // Step 2: pick increasing characters
        Character asc = map.higherKey(c);
        while (asc != null) {
            sb.append(asc);
            if (map.get(asc) == 1) map.remove(asc);
            else map.put(asc, map.get(asc) - 1);
            asc = map.higherKey(asc);
        }

        if (map.isEmpty()) break;

        // Step 4: pick largest character
        char d = map.lastKey();
        sb.append(d);
        if (map.get(d) == 1) map.remove(d);
        else map.put(d, map.get(d) - 1);

        // Step 5: pick decreasing characters
        Character desc = map.lowerKey(d);
        while (desc != null) {
            sb.append(desc);
            if (map.get(desc) == 1) map.remove(desc);
            else map.put(desc, map.get(desc) - 1);
            desc = map.lowerKey(desc);
        }
    }
    return sb.toString();
}

