public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;

    // DP: subsetsBySize[k] stores all possible sums of subsets of size k
    List<HashSet<Integer>> subsetsBySize = new ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) subsetsBySize.add(new HashSet<>());
    subsetsBySize.get(0).add(0);

    for (int num : nums) {
        // Update in reverse to avoid using the same number multiple times
        for (int size = n - 1; size >= 0; size--) {
            if (!subsetsBySize.get(size).isEmpty()) {
                HashSet<Integer> current = subsetsBySize.get(size);
                HashSet<Integer> next = subsetsBySize.get(size + 1);
                for (int sum : current) {
                    next.add(sum + num);
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long possible = (long) totalSum * k;
        if (possible % n != 0) continue;
        int target = (int) (possible / n);
        if (subsetsBySize.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            java.util.Set<Integer> prev = dp[k - 1];
            java.util.Set<Integer> cur = dp[k];
            for (int s : prev) {
                cur.add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // dp[k][s] is true if a subset of size k with sum s is achievable
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // iterate k in reverse to avoid reuse of the same element
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }

    // Check for any subset size k satisfying average equality
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n == 0) {
            int targetSum = (totalSum * k) / n;
            if (targetSum <= totalSum && dp[k][targetSum]) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    for (int k = 1; k <= n / 2; k++) {
        long mult = (long) totalSum * k;
        if (mult % n != 0) continue;
        int target = (int) (mult / n);
        if (canFindSubset(nums, k, target)) return true;
    }
    return false;
}

private boolean canFindSubset(int[] nums, int k, int target) {
    boolean[][] dp = new boolean[k + 1][target + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int size = k; size >= 1; size--) {
            for (int sum = target; sum >= num; sum--) {
                if (dp[size - 1][sum - num]) {
                    dp[size][sum] = true;
                }
            }
        }
    }
    return dp[k][target];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0; // start at step 1 and climb directly to the top
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1, prev2) + cost[i - 1];
        prev2 = prev1;
        prev1 = cur;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int prev = 0, cur = 0;
    for (int c : cost) {
        int next = c + (prev < cur ? prev : cur);
        prev = cur;
        cur = next;
    }
    return Math.min(prev, cur);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int uniqueMorseRepresentations(String[] words) {
    // Morse code mapping for the 26 letters of the alphabet
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.", "---",".--.",
                      "--.-",".-.", "...","-","..-","...-",".--","-..-","-.--","--..."};

