public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;          // the only binary string of length 0 is the empty string
    int n = s.length();
    if (n < k) return false;          // impossible to contain all codes if s is shorter than k

    int totalCodes = 1 << k;          // total possible binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;        // mask to keep only k bits

    int value = 0;
    // Build initial value for the first window of size k
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen[value] = true;
    int count = 1;

    // Slide the window over the rest of the string
    for (int i = k; i < n; i++) {
        // Shift left, drop the highest bit, add the new bit
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalCodes) return true; // early exit if all codes seen
        }
    }
    return count == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;  // An empty string is trivially present
    if (s == null || s.length() < k) return false;
    int total = 1 << k;       // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int count = 0;
    for (int i = 0; i <= s.length() - k; i++) {
        int val = 0;
        for (int j = 0; j < k; j++) {
            val = (val << 1) | (s.charAt(i + j) - '0');
        }
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true; // all codes found
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true; // empty k trivially satisfied
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;          // number of possible k‑bit codes
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // keeps only k bits
    int val = 0;
    // build initial value for first k characters
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    // slide window over the string
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true; // early exit if all codes found
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0 || n < k) return false;
    int required = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[required];
    int mask = required - 1; // mask to keep only k bits

    int code = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide through the string and update the code
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == required) {
                return true; // all codes have been seen
            }
        }
    }

    return count == required;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k <= 0) {
        return false;
    }
    int n = s.length();
    int total = 1 << k;              // total distinct binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int curr = 0;

    // Build the first k-bit pattern
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    seen[curr] = true;
    int count = 1;

    // Slide through the string, updating the bit pattern
    for (int i = k; i < n; i++) {
        curr = ((curr << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[curr]) {
            seen[curr] = true;
            if (++count == total) {
                return true; // early exit if all patterns are seen
            }
        }
    }
    return count == total;
}

