}

public int minInsertions(String s) {
    int balance = 0; // number of unmatched '('
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                // Need an additional '(' before this ')'
                insertions++;
            } else {
                balance--;
            }
        }
    }
    // Any remaining unmatched '(' need a ')' after
    insertions += balance;
    return insertions;
}

