public int minInsertions(String s) {
    int neededLeft = 0; // number of '(' we need to match current number of ')'
    int missingRight = 0; // number of ')' we have to insert
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            neededLeft++;
        } else { // c == ')'
            neededLeft--;
            if (neededLeft < 0) {
                // we need an extra '(' before this ')'
                missingRight++;
                neededLeft = 0;
            }
        }
    }
    // After processing all characters, we may still have unmatched '(' that need ')'
    return missingRight + neededLeft;
}

public int minOperations(int n) {
    long m, res;
    if ((n & 1) == 0) {
        m = n >> 1;
        res = m * m;
    } else {
        m = (n - 1) >> 1;
        res = m * (m + 1);
    }
    return (int) res;
}

public int minOperations(int n) {
    int target = n;
    int ops = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val > target) {
            ops += val - target;
        }
    }
    return ops;
}

