}

public int minOperations(int n) {
    int p = n / 2; // floor division
    if (n % 2 == 0) {
        long temp = (long) p * p;
        return (int) temp;
    } else {
        long temp = (long) p * (p + 1);
        return (int) temp;
    }
}

public int minOperations(int n) {
    // Compute the start index s as the first index with a positive difference
    int s = ((n - 1) / 2) + 1;
    int m = n - s;          // number of indices with positive difference
    return s * m;           // minimum number of operations
}

