public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;          // handle non‑positive edge case, though k is guaranteed ≥1
    // Generate all Fibonacci numbers ≤ k
    int[] fib = new int[50];
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 1;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) break;
        fib[size++] = next;
    }
    // Greedy selection: repeatedly choose the largest Fibonacci ≤ remaining
    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= remaining) {
                remaining -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

