public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxLarge = total - k; // index in large list for kth ascending factor
        return large.get(idxLarge);
    }
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    Collections.reverse(large);
    ArrayList<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    if (k <= 0 || k > all.size()) {
        return -1;
    }
    return all.get(k - 1);
}

public int kthFactor(int n, int k) {
