private void dfs(String s, int pos, java.util.Set<String> used, int count, int[] maxParts) {
    if (pos == s.length()) {
        if (count > maxParts[0]) {
            maxParts[0] = count;
        }
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
