public int maxUniqueSplit(String s) {
    int n = s.length();
    return dfs(0, n, s, new java.util.HashSet<>());
}

private int dfs(int pos, int n, String s, java.util.HashSet<String> used) {
    if (pos == n) {
        return 0;
    }
    int best = 0;
    StringBuilder sb = new StringBuilder();
    for (int i = pos; i < n; i++) {
        sb.append(s.charAt(i));
        String sub = sb.toString();
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        int res = dfs(i + 1, n, s, used);
        if (res >= 0) {
            best = Math.max(best, 1 + res);
        }
        used.remove(sub);
    }
    return best;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] best = new int[1];
    java.util.Set<String> used = new java.util.HashSet<>();
    backtrack(s, 0, used, 0, best, n);
    return best[0];
}

private void backtrack(String s, int pos, java.util.Set<String> used, int count, int[] best, int n) {
    if (pos == n) {
        if (count > best[0]) best[0] = count;
        return;
    }
    // pruning: maximum possible count from here is count + (n - pos)
    if (count + (n - pos) <= best[0]) return;
    for (int end = pos + 1; end <= n; end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, count + 1, best, n);
            used.remove(sub);
        }
    }
}

