public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int commonMask = ones & twos;
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    // Bit count array for each bit position
    int[] bitCnt = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            // Extract the i-th bit and add it to the count
            bitCnt[i] += (num >> i) & 1;
        }
    }
    // Reconstruct the unique number from the bit counts
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCnt[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = (long) num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
        if (lastDigit < 9) {
            long next = (long) num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

