public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result; // no non‑negative stepping numbers in negative range
    }
    // Include zero separately if it lies within the range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        long val = d;
        if (val >= low && val <= high) {
            result.add((int) val);
        }
        queue.offer(val);
    }
    while (!queue.isEmpty()) {
        long curr = queue.poll();
        long lastDigit = curr % 10;
        // Try to append lastDigit + 1
        if (lastDigit < 9) {
            long nextVal = curr * 10 + (lastDigit + 1);
            if (nextVal <= high) {
                if (nextVal >= low) {
                    result.add((int) nextVal);
                }
                queue.offer(nextVal);
            }
        }
        // Try to append lastDigit - 1
        if (lastDigit > 0) {
            long nextVal = curr * 10 + (lastDigit - 1);
            if (nextVal <= high) {
                if (nextVal >= low) {
                    result.add((int) nextVal);
                }
                queue.offer(nextVal);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Add single digit stepping numbers
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
    }

    // Use BFS to generate stepping numbers with more than one digit
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low && current >= 10) {
            result.add((int) current);
        }

        long lastDigit = current % 10;
        long[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (long nextDigit : nextDigits) {
            if (nextDigit < 0 || nextDigit > 9) continue;
            long nextNum = current * 10 + nextDigit;
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    result.sort(Integer::compareTo);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0 && high >= 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        bfs(i, low, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void bfs(int num, int low, int high, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(num);
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr > high) {
            continue;
        }
        if (curr >= low) {
            result.add(curr);
        }
        int lastDigit = curr % 10;

        int nextDigit = lastDigit - 1;
        if (nextDigit >= 0) {
            long newNum = (long) curr * 10 + nextDigit;
            if (newNum <= high) {
                queue.offer((int) newNum);
            }
        }

        nextDigit = lastDigit + 1;
        if (nextDigit <= 9) {
            long newNum = (long) curr * 10 + nextDigit;
            if (newNum <= high) {
                queue.offer((int) newNum);
            }
        }
    }
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long k = 1; k <= n; k *= 10) {
        long high = n / (k * 10);
        long cur = (n / k) % 10;
        long low = n % k;
        if (cur == 0) {
            count += high * k;
        } else if (cur == 1) {
            count += high * k + low + 1;
        } else {
            count += (high + 1) * k;
        }
        // Prevent potential overflow in k multiplication
        if (k > Long.MAX_VALUE / 10) {
            break;
        }
    }
    return (int) count;
}

