                antiDiag[i][j] = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;
                int lineLen = Math.max(
                        Math.max(horiz[i][j], vert[i][j]),
                        Math.max(diag[i][j], antiDiag[i][j]));
                if (lineLen > maxLen) maxLen = lineLen;
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                antiDiag[i][j] = 0;
            }
        }
    }
    return maxLen;
}

