                diag[i][j]  = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j] = (i > 0 && j + 1 < n ? antiDiag[i - 1][j + 1] : 0) + 1;

                int currentMax = Math.max(
                    Math.max(horiz[i][j], vert[i][j]),
                    Math.max(diag[i][j], antiDiag[i][j])
                );
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
