public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long val = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (val > 0) {
        sb.append(val % 10);
        val /= 10;
        count++;
        if (val > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

