}

private static void dfs(int prevIndex, int depth, int[] A, boolean[] visited, int[] result) {
    int n = A.length;
    if (depth == n) {
        result[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue; // skip duplicates
        if (prevIndex == -1 || isSquare(A[prevIndex] + A[i])) {
            visited[i] = true;
            dfs(i, depth + 1, A, visited, result);
            visited[i] = false;
        }
    }
}

private static boolean isSquare(int sum) {
    int r = (int) Math.sqrt(sum);
    return r * r == sum;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    // Build frequency map of unique values
    java.util.HashMap<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }
    // Build arrays of unique values and counts
    int m = freqMap.size();
    int[] vals = new int[m];
    int[] cnt = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        vals[idx] = e.getKey();
        cnt[idx] = e.getValue();
        idx++;
    }
    // Precompute valid pair matrix
    boolean[][] valid = new boolean[m][m];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            int sum = vals[i] + vals[j];
            int r = (int) Math.sqrt(sum);
            valid[i][j] = r * r == sum;
        }
    }
    // Memoization map
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();
    // Special index for no previous value
    final int NONE = m;
    // Define recursive function using lambda (Java 8)
    java.util.function.BiFunction<int[], Integer, Integer> dfs = new java.util.function.BiFunction<int[], Integer, Integer>() {
        public Integer apply(int[] remCnt, Integer lastIdx) {
            // Encode state into long key
            long key = 0L;
            for (int i = 0; i < m; i++) {
                key = (key << 4) | (remCnt[i] & 0xF);
            }
            key = (key << 4) | (lastIdx & 0xF);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            // Compute remaining total
            int remSum = 0;
            for (int c : remCnt) remSum += c;
            if (remSum == 0) {
                memo.put(key, 1);
                return 1;
            }
            int total = 0;
            for (int i = 0; i < m; i++) {
                if (remCnt[i] == 0) continue;
                if (lastIdx != NONE && !valid[lastIdx][i]) continue;
                remCnt[i]--;
                total += apply(remCnt, i);
                remCnt[i]++; // backtrack
            }
            memo.put(key, total);
            return total;
        }
    };
    int result = dfs.apply(cnt, NONE);
    return result;
}

