public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort to handle duplicates pruning
    java.util.Arrays.sort(A);
    // Precompute perfect squares up to max possible sum
    int maxSum = 2 * 10000; // assuming A[i] <= 10^4, adjust if needed
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build adjacency matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            can[i][j] = isSquare[A[i] + A[j]];
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    // Initialize with single elements
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long curWays = dp[mask][last];
            if (curWays == 0) continue;
            // Try to extend with next element
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue; // already used
                if (!can[last][next]) continue;
                // Prune duplicates: skip if there is a smaller unused index with same value
                boolean skip = false;
                for (int k = 0; k < next; k++) {
                    if (A[k] == A[next] && (mask & (1 << k)) == 0) {
                        skip = true;
                        break;
                    }
                }
                if (skip) continue;
                dp[mask | (1 << next)][next] += curWays;
            }
        }
    }
    long result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    // Result fits into int as per problem statement
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to max sum
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int k = 0; k * k <= maxSum; k++) {
        isSquare[k * k] = true;
    }
    // adjacency allowed matrix
    boolean[][] allowed = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            allowed[i][j] = isSquare[A[i] + A[j]];
        }
    }
    // Memoization map: key = (mask << 4) | lastIdx
    Map<Long, Long> memo = new HashMap<>();
    int fullMask = (1 << n) - 1;
    long total = 0;
    // Start with each possible first element
    for (int i = 0; i < n; i++) {
        // Skip duplicates at first position
        if (i > 0 && A[i] == A[i - 1]) continue;
        total += dfs(i, 1 << i, fullMask, allowed, memo);
    }
    return (int) total;

    // Helper recursive function
    static long dfs(int lastIdx, int mask, int fullMask, boolean[][] allowed, Map<Long, Long> memo) {
        if (mask == fullMask) return 1;
        long key = ((long) mask << 5) | lastIdx; // 5 bits enough for n <=32
        if (memo.containsKey(key)) return memo.get(key);
        long res = 0;
        int n = allowed.length;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) continue;           // already used
            if (!allowed[lastIdx][i]) continue;             // adjacency not allowed
            // Skip duplicate value at this recursion level
            if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
            res += dfs(i, mask | (1 << i), fullMask, allowed, memo);
        }
        memo.put(key, res);
        return res;
    }
}

