public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute adjacency matrix
    boolean[][] edge = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int sqrt = (int)Math.sqrt(sum);
                if (sqrt * sqrt == sum) {
                    edge[i][j] = true;
                }
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    // Initialize dp for each starting index with duplicate handling
    for (int i = 0; i < n; i++) {
        int mask = 1 << i;
        if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) {
            // Skip duplicate starting index
            continue;
        }
        dp[mask][i] = 1;
    }
    // DP over masks
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            // Try to add a next element
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue; // already used
                if (!edge[last][next]) continue; // sum not perfect square
                // Skip duplicates: ensure that for identical values, we only pick the earliest unused one
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) {
                    continue;
                }
                int nextMask = mask | (1 << next);
                dp[nextMask][next] += cur;
            }
        }
    }
    // Sum over all full masks
    int answer = 0;
    for (int last = 0; last < n; last++) {
        answer += dp[fullMask][last];
    }
    return answer;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = 0; // number of elements in stack

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top > 0 && currentHeight < heights[stack[top - 1]]) {
            int height = heights[stack[--top]];
            int width = (top == 0) ? i : i - stack[top - 1] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    return maxArea;
}

