public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int d = 0; d < m + n - 1; d++) {
        if (d % 2 == 0) {
            // even diagonal: traverse from bottom to top
            int r = d < m ? d : m - 1;
            int c = d - r;
            while (r >= 0 && c < n) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // odd diagonal: traverse from top to bottom
            int r, c;
            if (d < n) {
                r = 0;
                c = d;
            } else {
                r = d - n + 1;
                c = n - 1;
            }
            while (r < m && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

