        if (sum % 2 == 0) { // even sum: traverse from bottom to top
            int start = Math.min(sum, m - 1);
            int end = Math.max(0, sum - (n - 1));
            for (int i = start; i >= end; i--) {
                result[idx++] = mat[i][sum - i];
            }
        } else { // odd sum: traverse from top to bottom
            int start = Math.max(0, sum - (n - 1));
            int end = Math.min(sum, m - 1);
            for (int i = start; i <= end; i++) {
                result[idx++] = mat[i][sum - i];
            }
        }
    }
    return result;
}

