    for (int sum = 0; sum < m + n - 1; sum++) {
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);
        int len = endRow - startRow + 1;
        int[] temp = new int[len];
        int t = 0;
        for (int row = startRow; row <= endRow; row++) {
            int col = sum - row;
            temp[t++] = mat[row][col];
        }
        if (sum % 2 == 0) {
            for (int j = len - 1; j >= 0; j--) {
                result[idx++] = temp[j];
            }
        } else {
            for (int j = 0; j < len; j++) {
                result[idx++] = temp[j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    // Step 1: find the largest index i such that digits[i] < digits[i + 1]
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    // If no such index exists, this is the highest permutation
    if (i < 0) {
        return -1;
    }
    // Step 2: find the largest index j greater than i such that digits[j] > digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i + 1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert the resulting digit array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // The resulting number is out of int range
        return -1;
    }
}

