        return -1;
    }
    // Convert number to array of digits
    int len = Integer.toString(n).length();
    int[] digits = new int[len];
    int temp = n;
    for (int i = len - 1; i >= 0; i--) {
        digits[i] = temp % 10;
        temp /= 10;
    }

    // Find the first index from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // No next permutation
    }

    // Find the smallest digit on the right side of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    int tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;

    // Reverse the subarray from i+1 to the end
    int left = i + 1, right = len - 1;
    while (left < right) {
        tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Construct the resulting integer
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
