private static void buildSymmetric(int left, int n, char[] current,
                                   char[][] pairs, List<String> result) {
    if (left >= (n + 1) / 2) {
        result.add(new String(current));
        return;
    }
    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0' && n > 1) continue; // avoid leading zero
        current[left] = pair[0];
        current[n - 1 - left] = pair[1];
        buildSymmetric(left + 1, n, current, pairs, result);
    }
}

