private static void buildSymmetric(int left, int right, char[] current, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        char[] centers = {'0', '1', '8'};
        for (char c : centers) {
            current[left] = c;
            result.add(new String(current));
        }
        return;
    }
    char[][] pairsNoZero;
    if (left == 0) {
        pairsNoZero = new char[][]{{'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    } else {
        pairsNoZero = new char[][]{{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    }
    for (char[] p : pairsNoZero) {
        current[left] = p[0];
        current[right] = p[1];
        buildSymmetric(left + 1, right - 1, current, result);
    }
}

