private static List<String> build(int curr, int total) {
    if (curr == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (curr == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> prev = build(curr - 2, total);
    List<String> res = new ArrayList<>();
    for (String middle : prev) {
        if (curr != total) {
            res.add("0" + middle + "0");
        }
        res.add("1" + middle + "1");
        res.add("6" + middle + "9");
        res.add("8" + middle + "8");
        res.add("9" + middle + "6");
    }
    return res;
}

