    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    // Check the last run
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

