public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int curr, int n, List<Integer> res) {
    res.add(curr);
    long currLong = curr;
    for (int i = 0; i < 10; i++) {
        long next = currLong * 10 + i;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

