public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Base case: dp[0] is 0 (zero sum requires zero squares)
    dp[0] = 0;
    // Initialize dp[i] with the maximum possible value (i, using all 1's)
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
            j++;
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) {
            return 2;
        }
    }
    // Check Legendre's three-square theorem for 4
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    // If not 1, 2, or 4, it must be 3
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int k = 1; k * k <= i; k++) {
            int square = k * k;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int i = 0;
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int j = i;
            while (j < n && s.charAt(j) != ' ') {
                j++;
            }
            String word = s.substring(i, j);
            result.append(new StringBuilder(word).reverse());
            i = j;
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(c);
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        for (int j = word.length() - 1; j >= 0; j--) {
            result.append(word.charAt(j));
        }
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

